import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, useSearchParam } from '../../url/useSearchParam';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/** One of a person's grades, in force from its from-date (yyyy-MM-dd; null when it applies from the beginning of time). */
export type GradeFrom = { grade: Grade; from: string | null };

// grade is the one in force on the sheet's today; grades are every one recorded, by from-date.
// retiredFrom is null unless the person is retired; once set, they count as retired whatever the date.
// While held, their OPEN claims count in no live total; their SETTLED ones still do.
export type Person = {
  id: number;
  name: string;
  grade: Grade;
  version: number;
  retiredFrom: string | null;
  held: boolean;
  grades: GradeFrom[];
};

/** The person's grade in force on a date (yyyy-MM-dd): the one whose from-date is the latest on or before it. */
export function gradeOn(person: Person, date: string): Grade | undefined {
  let found: GradeFrom | undefined;
  for (const g of person.grades) {
    if (g.from !== null && g.from > date) continue;
    if (found === undefined || (found.from ?? '') < (g.from ?? '')) found = g;
  }
  return found?.grade;
}

export const isRetired = (p: Person) => p.retiredFrom !== null;

export const peopleKey = (sheet: string) => ['people', sheet] as const;

export const peoplePath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/people`;

/** Everyone on the sheet, in the order they were added. */
export function usePeople(sheet: string) {
  return useQuery({
    queryKey: peopleKey(sheet),
    queryFn: () => getJson<Person[]>(peoplePath(sheet)),
  });
}

/** Whether retired people are listed: off until turned on, and kept in the URL so loading a sheet leaves it be. */
export const useShowRetired = () => useSearchParam('retired', asFlag);
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { gradeOn, usePeople } from '../people/people';
import { rateOf, twoDecimals, useRates } from '../rates/rates';
import { useFloorCents } from '../settings/settings';
import { claimDueCents, counted, useClaims, useLate } from '../claims/claims';
import { closePeriodPath, periodOf, reopenPeriodPath, periodsKey, periodsPath, usePeriods } from './periods';
import type { Period } from './periods';

// One period with its due-total (fixed once closed) and closed flag, and the buttons that close and reopen it. The
// server refuses closing a period already closed, and reopening one not closed or by anyone but a steward; the row
// shows that error until its next action.
function PeriodRow({ sheet, user, period, dueCents }: { sheet: string; user: string; period: Period; dueCents: bigint }) {
  const queryClient = useQueryClient();
  const close = useMutation({
    mutationFn: () => postJson<Period[]>(byUser(closePeriodPath(sheet, period.name), user), {}),
    onSuccess: (updated) => queryClient.setQueryData(periodsKey(sheet), updated),
  });
  const reopen = useMutation({
    mutationFn: () => postJson<Period[]>(byUser(reopenPeriodPath(sheet, period.name), user), {}),
    onSuccess: (updated) => queryClient.setQueryData(periodsKey(sheet), updated),
  });
  const closeOnce = useSubmitOnce(close);
  const reopenOnce = useSubmitOnce(reopen);

  return (
    <tr data-testid={`period-row-${period.name}`}>
      <td data-testid="period-name">{period.name}</td>
      <td data-testid="period-from">{period.from}</td>
      <td data-testid="period-to">{period.to}</td>
      <td data-testid="period-due-total">{period.closed && period.closedTotal !== null ? period.closedTotal : twoDecimals(dueCents)}</td>
      <td data-testid="period-closed">{period.closed ? 'yes' : 'no'}</td>
      <td>
        <button
          type="button"
          data-testid="period-close"
          disabled={close.isPending || reopen.isPending}
          onClick={() => {
            reopen.reset();
            closeOnce(undefined);
          }}
        >
          Close
        </button>{' '}
        <button
          type="button"
          data-testid="period-reopen"
          disabled={close.isPending || reopen.isPending}
          onClick={() => {
            close.reset();
            reopenOnce(undefined);
          }}
        >
          Reopen
        </button>
        {close.isError && (
          <span data-testid="period-error" role="alert">
            {' '}This period cannot be closed: it is already closed.
          </span>
        )}
        {reopen.isError && (
          <span data-testid="period-error" role="alert">
            {' '}This period cannot be reopened: it is not closed, or you are not a steward.
          </span>
        )}
      </td>
    </tr>
  );
}

type Draft = { name: string; from: string; to: string };
const EMPTY: Draft = { name: '', from: '', to: '' };

// The sheet's periods, each with its due-total: the due of the counted (OPEN and SETTLED, but not a held person's OPEN) claims whose date
// falls in it (a claim with no rate adds nothing), fixed when the period is closed. The form adds one; the server refuses a name already on
// the sheet, a bad date, a to-date before the from-date, or dates that overlap another period.
function Periods({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const { data: periods = [] } = usePeriods(sheet);
  const { data: all = [] } = useClaims(sheet);
  const { data: people = [] } = usePeople(sheet);
  const { data: rates = [] } = useRates(sheet);
  const floor = useFloorCents(sheet);
  const late = useLate(sheet);
  const [draft, setDraft] = useState<Draft>(EMPTY);

  const save = useMutation({
    mutationFn: (body: Draft) => postJson<Period[]>(byUser(periodsPath(sheet), user), body),
    onSuccess: (updated) => {
      queryClient.setQueryData(periodsKey(sheet), updated);
      setDraft(EMPTY);
    },
  });
  const send = useSubmitOnce(save);

  const change = (next: Partial<Draft>) => {
    setDraft((d) => ({ ...d, ...next }));
    save.reset();
  };

  const submit = (e: FormEvent) => {
    e.preventDefault();
    send(draft);
  };

  const byId = new Map(people.map((p) => [p.id, p]));
  const totals = new Map<string, bigint>();
  for (const c of counted(all, people)) {
    const period = periodOf(periods, c.date);
    const person = byId.get(c.person);
    if (period === undefined || person === undefined) continue;
    const grade = gradeOn(person, c.date);
    const due = claimDueCents(c, rateOf(rates, grade, c.date), floor, late) ?? 0n;
    totals.set(period.name, (totals.get(period.name) ?? 0n) + due);
  }

  return (
    <section>
      <h2>Periods</h2>
      <form onSubmit={submit}>
        <label>
          Name{' '}
          <input data-testid="period-form-name" value={draft.name} onChange={(e) => change({ name: e.target.value })} />
        </label>{' '}
        <label>
          From{' '}
          <input
            data-testid="period-form-from"
            placeholder="yyyy-mm-dd (blank: today)"
            value={draft.from}
            onChange={(e) => change({ from: e.target.value })}
          />
        </label>{' '}
        <label>
          To{' '}
          <input
            data-testid="period-form-to"
            placeholder="yyyy-mm-dd"
            value={draft.to}
            onChange={(e) => change({ to: e.target.value })}
          />
        </label>{' '}
        <button type="submit" data-testid="period-form-submit" disabled={save.isPending}>
          Add period
        </button>
        {save.isError && (
          <span data-testid="period-form-error" role="alert">
            {' '}A period needs a name not already on the sheet and valid from and to dates, the to on or after the from, that overlap no other period.
          </span>
        )}
      </form>
      <table>
        <thead>
          <tr>
